def has_close_elements(numbers: List[float], threshold: float) -> bool:
    numbers_sorted = sorted(float(x) for x in numbers)
    for a, b in zip(numbers_sorted, numbers_sorted[1:]):
        if b - a < threshold:
            return True
    return False

from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    groups: List[str] = []
    curr: List[str] = []
    depth = 0

    for ch in paren_string:
        if ch == " ":
            continue
        if ch == "(":
            if depth == 0:
                curr = []
            curr.append(ch)
            depth += 1
        else:  # ch == ")"
            curr.append(ch)
            depth -= 1
            if depth == 0:
                groups.append("".join(curr))

    return groups

