    assert all(type(num) == int and num > 0 for num in x), "invalid inputs"  # $_CONTRACT_$

    def has_no_even_digit(n):
        while n:
            d = n % 10
            if d % 2 == 0:
                return False
            n //= 10
        return True

    return sorted([num for num in x if has_no_even_digit(num)])

def even_odd_palindrome(n):
    assert type(n) == int, "invalid inputs"
    assert 1 <= n <= 1000, "invalid inputs"

    even_count = 0
    odd_count = 0

    for i in range(1, n + 1):
        s = str(i)
        if s == s[::-1]:
            if i % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return (even_count, odd_count)

def count_nums(arr):
    assert type(arr) == list, "invalid inputs"
    assert all(type(x) == int for x in arr), "invalid inputs"

    def signed_digit_sum(n):
        if n == 0:
            return 0
        sign = -1 if n < 0 else 1
        s = str(abs(n))
        total = sign * int(s[0])
        for ch in s[1:]:
            total += int(ch)
        return total

    return sum(1 for x in arr if signed_digit_sum(x) > 0)

def move_one_ball(arr):
    assert type(arr) == list, "invalid inputs"
    assert all(type(x) == int for x in arr), "invalid inputs"
    assert len(set(arr)) == len(arr), "invalid inputs"
    assert all(type(x) == int for x in arr), "invalid inputs"

    n = len(arr)
    if n <= 1:
        return True

    breaks = 0
    for i in range(n):
        if arr[i] > arr[(i + 1) % n]:
            breaks += 1
            if breaks > 1:
                return False
    return True

