    assert isinstance(test, str), "invalid inputs"
    words = test.split(" ")
    for word in words:
        if word != "":
            assert len(word) == 1 and word.islower(), "invalid inputs"

    counts = {}
    for w in words:
        if w:
            counts[w] = counts.get(w, 0) + 1

    if not counts:
        return {}

    max_count = max(counts.values())
    return {k: v for k, v in counts.items() if v == max_count}

