def iscube(a):
    if a == 0:
        return True
    sign = -1 if a < 0 else 1
    n = abs(a)

    lo, hi = 0, 1
    while hi * hi * hi < n:
        hi <<= 1

    while lo <= hi:
        mid = (lo + hi) // 2
        c = mid * mid * mid
        if c == n:
            return True
        if c < n:
            lo = mid + 1
        else:
            hi = mid - 1
    return False

