def count_up_to(n):
    assert type(n) == int and n >= 0, "invalid inputs"  # $_CONTRACT_$
    if n <= 2:
        return []
    sieve = bytearray(b"\x01") * n
    sieve[0:2] = b"\x00\x00"
    limit = int((n - 1) ** 0.5)
    for p in range(2, limit + 1):
        if sieve[p]:
            start = p * p
            step = p
            sieve[start:n:step] = b"\x00" * (((n - 1 - start) // step) + 1)
    return [i for i in range(2, n) if sieve[i]]

