def starts_one_ends(n):
    """
    Given a positive integer n, return the count of the numbers of n-digit
    positive integers that start or end with 1.
    """
    assert type(n) == int and n > 0, "invalid inputs" # $_CONTRACT_$
    if n == 1:
        return 2
    else:
        return 9 * (10**(n-2)) + (10**(n-1)) + (10**(n-1)) - 1

def count_up_to(n):
    """Implement a function that takes an non-negative integer and returns an array of the first n
    integers that are prime numbers and less than n.
    for example:
    count_up_to(5) => [2,3]
    count_up_to(11) => [2,3,5,7]
    count_up_to(0) => []
    count_up_to(20) => [2,3,5,7,11,13,17,19]
    count_up_to(1) => []
    count_up_to(18) => [2,3,5,7,11,13,17]
    """

    assert type(n) == int and n >= 0, "invalid inputs" # $_CONTRACT_$

    def is_prime(num):
        if num <= 1:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    prime_nums = []
    for i in range(2, n):
        if is_prime(i):
            prime_nums.append(i)
        if len(prime_nums) == n:
            break
    return prime_nums

from typing import List

def has_close_elements(numbers: List[float], threshold: float) -> bool:
    assert isinstance(threshold, float) and threshold > 0, "invalid inputs" # $_CONTRACT_$
    assert isinstance(numbers, list), "invalid inputs" # $_CONTRACT_$
    assert all([isinstance(v, (int, float)) for v in numbers]), "invalid inputs" # $_CONTRACT_$

    for i in range(len(numbers) - 1):
        for j in range(i + 1, len(numbers)):
            if abs(numbers[i] - numbers[j]) < threshold:
                return True
    return False

def is_palindrome(string: str) -> bool:
    return string == string[::-1]


def make_palindrome(string: str) -> str:
    if not is_palindrome(string):
        longest_postfix = ""
        for i in range(len(string)):
            if is_palindrome(string[i:]):
                longest_postfix = string[i:]
        prefix = string[:-1 * len(longest_postfix)]
        return f"{prefix}{longest_postfix[::-1]}"
    else:
        return string

def make_a_pile(n):
    if not isinstance(n, int) or n < 1:
        raise ValueError("Invalid input")

    pile = []
    while n > 0:
        pile.append(n)
        n = (n + 1) // 2 if n % 2 else (n + 1) // 2 * 2

    return pile

def choose_num(x, y):
    if x % 2 == 0:
        if y % 2 == 0:
            return max(x, y)
        else:
            return max(x, y - 1)
    else:
        if y % 2 == 0:
            return max(x + 1, y)
        else:
            return max(x + 1, y - 1)

def rounded_avg(n, m):
    if n > m:
        return -1
    sum = 0
    for i in range(n, m+1):
        sum += i
    avg = sum / (m-n+1)
    return bin(round(avg))[2:]

def by_length(arr):
