def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    assert isinstance(test, str), "invalid inputs" # $_CONTRACT_$
    words = test.split(" ") # $_CONTRACT_$
    for word in words: # $_CONTRACT_$
        if word != "": # $_CONTRACT_$
            assert len(word) == 1 and word.islower(), "invalid inputs" # $_CONTRACT_$

    letter_count = {}
    for word in words:
        if word not in letter_count:
            letter_count[word] = 1
        else:
            letter_count[word] += 1

    max_count = max(letter_count.values())
    result = {k: v for k, v in letter_count.items() if v == max_count}
    return result

def reverse_delete(s, c):
    result = ""
    for i in range(len(s)):
        if s[i] not in c:
            result += s[i]
    return (result, result == result[::-1])

def select_words(s, n):
    if not s:
        return []
    words = s.split()
    consonants = ["b", "c", "d", "f", "g", "h", "j", "k", "l", "m", "n", "p", "q", "r", "s", "t", "v", "w", "x", "y", "z"]
    result = []
    for word in words:
        if len([ch for ch in word if ch.isalpha() and ch.lower() not in consonants]) == n:
            result.append(word)
    return result

def match_parens(lst):
    """
    Return 'Yes' if there's a way to make a good string, and return 'No' otherwise.
    """
    stack = []
    for char in lst[0] + lst[1]:
        if char == "(":
            stack.append(char)
        elif char == ")":
            if not stack or stack.pop() != "(":
                return "No"
    return "Yes" if not stack else "No"

def longest(strings: List[str]) -> Optional[str]:
    if not strings:
