def is_sorted(lst):
    if len(lst) <= 1:
        return True
    for i in range(len(lst) - 1):
        if lst[i] > lst[i + 1]:
            return False
    return True

def intersection(interval1, interval2):
    if not (len(interval1) == 2 and interval1[0] <= interval1[1] and len(interval2) == 2 and interval2[0] <= interval2[1]):
        return "NO"
    start = max(interval1[0], interval2[0])
    end = min(interval1[1], interval2[1])
    if start > end:
        return "NO"
    length = end - start + 1
    if length == 1 or length % 2 == 0 and length % 3 == 0:
        return "YES"
    else:
        return "NO"

def prod_signs(arr):
    if not arr:
        return None
    product = 1
    for num in arr:
        sign = 1 if num > 0 else -1 if num < 0 else 0
        product *= sign
    return product

def greatest_common_divisor(a: int, b: int) -> int:
    """ Return a greatest common divisor of two integers a and b
    >>> greatest_common_divisor(3, 5)
    1
    >>> greatest_common_divisor(25, 15)
    5
    """
    assert type(a) == int and type(b) == int, "invalid inputs" # $_CONTRACT_$
    assert a > 0 and b > 0, "invalid inputs" # $_CONTRACT_$
    if a == b:
        return a
    elif a < b:
        return greatest_common_divisor(b % a, a)
    else:
        return greatest_common_divisor(a % b, b)

def tri(n):
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return [1]
    elif n % 2 == 0:
        return [1, n / 2] + tri(n - 2)
    else:
        return [1, tri(n - 1), tri(n - 2), tri(n + 1)]

def digits(n):
    if n < 1:
        return 0
    product = 1
    while n > 0:
        digit = n % 10
        if digit % 2 == 1:
            product *= digit
        n //= 10
    return product

def is_nested(string):
    stack = []
    for char in string:
        if char == "[":
            stack.append(char)
        elif char == "]":
            if not stack:
                return False
            stack.pop()
    return not stack

