        balance = 0
        for char in s:
            if char == '(':
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    s1, s2 = lst[0], lst[1]
    return 'Yes' if is_balanced(s1 + s2) or is_balanced(s2 + s1) else 'No'

