    if not isinstance(date, str) or len(date) == 0:
        return False

    pattern = r'^(\d{2})-(\d{2})-(\d{4})$'
    match = re.match(pattern, date)
    if not match:
        return False

    month, day, year = map(int, match.groups())

    if month < 1 or month > 12:
        return False

    days_in_month = [31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    if month != 2:
        if day < 1 or day > days_in_month[month - 1]:
            return False
    else:
        if not (year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)):
            if day < 1 or day > 28:
                return False

    return True

def split_words(txt):
    if ' ' in txt:
        return txt.split()
    elif ',' in txt:
        return txt.split(',')
    else:
        count = 0
        for char in txt:
            if ord('a') <= ord(char) <= ord('z'):
                count += (ord(char) - ord('a')) % 2 == 1
        return count

def is_sorted(lst):
    seen = set()
    for i in range(len(lst)):
        if lst[i] in seen:
            return False
        seen.add(lst[i])
        if i > 0 and lst[i] < lst[i - 1]:
            return False
    return True

def intersection(interval1, interval2):
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    # Find the intersection of the two intervals
    start_intersection = max(interval1[0], interval2[0])
    end_intersection = min(interval1[1], interval2[1])

    if start_intersection <= end_intersection:
        length_of_intersection = end_intersection - start_intersection + 1
        return "YES" if is_prime(length_of_intersection) else "NO"
    else:
        return "NO"

