def prod_signs(arr):
    if not arr:
        return None

    product_of_signs = 1
    sum_of_magnitudes = 0

    for num in arr:
        assert type(num) == int, "invalid inputs"
        sum_of_magnitudes += abs(num)
        if num > 0:
            product_of_signs *= 1
        elif num < 0:
            product_of_signs *= -1
        else:
            product_of_signs *= 0

    return sum_of_magnitudes * product_of_signs

import heapq

def minPath(grid, k):
    N = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def is_valid(x, y):
        return 0 <= x < N and 0 <= y < N

    # Priority queue to store the paths with their sums
    pq = []
    for i in range(N):
        for j in range(N):
            heapq.heappush(pq, (grid[i][j], [(i, j)]))

    while pq:
        current_sum, path = heapq.heappop(pq)

        if len(path) == k:
            return [grid[x][y] for x, y in path]

        last_x, last_y = path[-1]

        for dx, dy in directions:
            new_x, new_y = last_x + dx, last_y + dy
            if is_valid(new_x, new_y) and (new_x, new_y) not in path:
                new_path = path + [(new_x, new_y)]
                heapq.heappush(pq, (current_sum + grid[new_x][new_y], new_path))

    return []

def tri(n):
    if n < 0:
        return []

    tribonacci = [1] * (n + 1)
    tribonacci[0] = 3

    for i in range(2, n + 1):
        if i % 2 == 0:
            tribonacci[i] = 1 + i / 2
        else:
            tribonacci[i] = tribonacci[i - 1] + tribonacci[i - 2] + tribonacci[i + 1]

    return tribonacci

def digits(n):
    product = 1
    for digit in str(n):
        if int(digit) % 2 != 0:
            product *= int(digit)
    return product if n > 0 else 0

def is_nested(string):
    stack = []
    for char in string:
        if char == '[':
            stack.append(char)
        elif char == ']':
            if stack and stack[-1] == '[':
                stack.pop()
            else:
                return True
    return len(stack) == 0

def check_if_last_char_is_a_letter(txt):
    if not isinstance(txt, str) or len(txt) == 0:
        return False
    last_char = txt[-1]
    return last_char.isalpha() and (len(txt) == 1 or txt[len(txt)-2] == ' ')

def largest_smallest_integers(lst):
    negatives = [num for num in lst if num < 0]
    positives = [num for num in lst if num > 0]

    a = max(negatives) if negatives else None
    b = min(positives) if positives else None

    return (a, b)

def compare_one(a, b):
    def to_float(x):
        try:
            return float(str(x).replace(",", "."))
        except ValueError:
            return None

    a_float = to_float(a)
    b_float = to_float(b)

    if a_float is not None and b_float is not None:
        if a_float > b_float:
            return a_float
        elif a_float < b_float:
            return b_float
        else:
            return None
    elif a_float is not None:
        return a_float
    elif b_float is not None:
        return b_float
    else:
        return None

def special_factorial(n):
    def factorial(num):
        if num == 0 or num == 1:
            return 1
        else:
            return num * factorial(num - 1)

    result = 1
    for i in range(1, n + 1):
        result *= factorial(i)
    return result

from typing import List

def all_prefixes(string: str) -> List[str]:
    return [string[:i] for i in range(1, len(string) + 1)]

def fix_spaces(text):
    if not isinstance(text, str):
        raise ValueError("invalid inputs")

    result = []
    for char in text:
        if char == ' ':
            if len(result) > 0 and result[-1] != '_':
                result.append('_')
        else:
            result.append(char)
    return ''.join(result).replace('__', '_')

def file_name_check(file_name):
    if not isinstance(file_name, str):
        return 'No'

    parts = file_name.split('.')
    if len(parts) != 2 or not parts[0] or not parts[1]:
        return 'No'

    if not parts[0][0].isalpha() or any(c.isdigit() for c in parts[0]):
        return 'No'

    valid_extensions = ['txt', 'exe', 'dll']
    if parts[1] not in valid_extensions:
        return 'No'

    return 'Yes'

def sum_squares(lst):
    result = 0
    for i, num in enumerate(lst):
        if i % 3 == 0:
            result += num ** 2
        elif i % 4 == 0 and i % 3 != 0:
            result += num ** 3
        else:
            result += num
    return result

def words_in_sentence(sentence):
    def is_prime(n):
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    words = sentence.split()
    prime_length_words = [word for word in words if is_prime(len(word))]
    return ' '.join(prime_length_words)

def specialFilter(nums):
    def is_odd(digit):
        return digit % 2 != 0

    def first_and_last_are_odd(number):
        digits = [int(d) for d in str(abs(number))]
        return is_odd(digits[0]) and is_odd(digits[-1])

    filtered_nums = [num for num in nums if num > 10 and first_and_last_are_odd(num)]
    return len(filtered_nums)

def get_max_triples(n):
    a = [i * i - i + 1 for i in range(1, n + 1)]
    count = 0
    for i in range(n - 2):
        for j in range(i + 1, n - 1):
            for k in range(j + 1, n):
                if (a[i] + a[j] + a[k]) % 3 == 0:
                    count += 1
    return count

def bf(planet1, planet2):
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]
    if not (isinstance(planet1, str) and isinstance(planet2, str)):
        return ()

    if planet1 not in planets or planet2 not in planets:
        return ()

    index1 = planets.index(planet1)
    index2 = planets.index(planet2)

    if index1 > index2:
        index1, index2 = index2, index1

    return tuple(planets[i] for i in range(index1 + 1, index2))

def is_prime(num):
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5

    """
    assert type(n) == int, "invalid inputs"
    return x if is_prime(n) else y

def double_the_difference(lst):
    valid_numbers = [num for num in lst if isinstance(num, int) and num >= 0]
    odd_squares = [num**2 for num in valid_numbers if num % 2 != 0]
    return sum(odd_squares)

def cycpattern_check(a, b):
    if not (isinstance(a, str) and isinstance(b, str)):
        raise ValueError("invalid inputs")

    rotations = [b[i:] + b[:i] for i in range(len(b))]
    return any(rotation in a for rotation in rotations)

def even_odd_count(num):
    num = abs(num)
    even_count = 0
    odd_count = 0
    while num > 0:
        digit = num % 10
        if digit % 2 == 0:
            even_count += 1
        else:
            odd_count += 1
        num //= 10
    return (even_count, odd_count)

def find_max(words):
    def unique_char_count(word):
        return len(set(word))

    max_unique = -1
    result = ""

    for word in words:
        unique_count = unique_char_count(word)
        if unique_count > max_unique or (unique_count == max_unique and word < result):
            max_unique = unique_count
            result = word

    return result

def count_distinct_characters(string: str) -> int:
    seen = set()
    for char in string.lower():
        if char.isalpha():
            seen.add(char)
    return len(seen)

def do_algebra(operator, operand):
    result = operand[0]
    for i in range(len(operator)):
        if operator[i] == '+':
            result += operand[i + 1]
        elif operator[i] == '-':
            result -= operand[i + 1]
        elif operator[i] == '*':
            result *= operand[i + 1]
        elif operator[i] == '//':
            if operand[i + 1] != 0:
                result //= operand[i + 1]
        elif operator[i] == '**':
            result **= operand[i + 1]
    return result

def solve(s):
    if not s.isalpha():
        return s[::-1]
    result = []
    for char in s:
        if char.islower():
            result.append(char.upper())
        elif char.isupper():
            result.append(char.lower())
        else:
            result.append(char)
    return ''.join(result)

import hashlib

def string_to_md5(text):
    if not isinstance(text, str) or text == '':
        return None
    md5 = hashlib.md5()
    md5.update(text.encode('utf-8'))
    return md5.hexdigest()

from typing import List

def parse_music(music_string: str) -> List[int]:
    if not isinstance(music_string, str):
        raise ValueError("Invalid input: expected a string")

    notes = music_string.split()
    valid_notes = {"o", "o|", ".|"}
    if any(note not in valid_notes for note in notes):
        raise ValueError("Invalid input: contains invalid musical note characters")

    beats = []
    for note in notes:
        if note == 'o':
            beats.append(4)
        elif note == 'o|':
            beats.append(2)
        elif note == '.|':
            beats.append(1)

    return beats

def how_many_times(string: str, substring: str) -> int:
    count = start = 0
    while True:
        start = string.find(substring, start) + 1
        if start > 0:
            count += 1
        else:
            break
    return count

from typing import List

def rescale_to_unit(numbers: List[float]) -> List[float]:
    assert all(type(x) in [int, float] for x in numbers), "invalid inputs"
    assert len(numbers) >= 2, "invalid inputs"
    assert max(numbers) > min(numbers), "invalid inputs"

    if max(numbers) == min(numbers):
        return [0.0] * len(numbers)

    rescaled = [(x - min(numbers)) / (max(numbers) - min(numbers)) for x in numbers]
    return rescaled

