import math

def poly(xs: list, x: float):
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])

def find_zero(xs: list):
    assert isinstance(xs, list) and len(xs) > 0 and len(xs) % 2 == 0, "invalid inputs"
    assert xs[-1] != 0, "invalid inputs"
    assert all(type(x) == int for x in xs), "invalid inputs"
    dxs = [xs[i] * i for i in range(1, len(xs))]

    def func(x):
        return poly(xs, x)

    def derivative(x):
        return poly(dxs, x)

    x, tol = 0, 1e-5
    for _ in range(1000):
        fx = func(x)
        dfx = derivative(x)
        if abs(fx) < tol: break
        x = x - fx / dfx

    assert abs(poly(xs, x)) < tol, "invalid inputs"
    return x

def sort_third(l: list):
    third = [x for i, x in enumerate(l) if i % 3 == 0]
    sorted_third = sorted(third)
    result = l[:]
    index = 0
    for i in range(len(result)):
        if i % 3 == 0:
            result[i] = sorted_third[index]
            index += 1
    return result

def unique(l: list):
    assert type(l) == list, "invalid inputs"
    return sorted(set(l))

def fizz_buzz(n: int):
    count = 0
    for i in range(1, n):
        if i % 11 == 0 or i % 13 == 0:
            if '7' in str(i):
                count += 1
    return count

def sort_even(l: list):
    evens = sorted([x for x in l if isinstance(x, (int, float)) and not isinstance(x, bool)])
    result = []
    even_index = 0
    for i in range(len(l)):
        if i % 2 == 0:
            result.append(evens[even_index])
            even_index += 1
        else:
            result.append(l[i])
    return result

def decode_cyclic(s: str):
    groups = [s[(3 * i):min((3 * i + 3), len(s))] for i in range((len(s) + 2) // 3)]
    decoded_groups = [(group[-1] + group[:-1]) if len(group) == 3 else group for group in groups]
    return "".join(decoded_groups)

def prime_fib(n: int):
    def is_prime(num):
        if num <= 1:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    def fib():
        a, b = 0, 1
        while True:
            yield a
            a, b = b, a + b

    primes_fibonacci = []
    for num in fib():
        if is_prime(num):
            primes_fibonacci.append(num)
        if len(primes_fibonacci) == n:
            return primes_fibonacci[-1]

