def remove_vowels(text):
    vowels = "aeiouAEIOU"
    return ''.join([char for char in text if char not in vowels])

def correct_bracketing(brackets: str):
    stack = []
    for bracket in brackets:
        if bracket == '<':
            stack.append(bracket)
        elif bracket == '>':
            if not stack:
                return False
            stack.pop()
    return len(stack) == 0

def largest_prime_factor(n: int):
    def is_prime(a):
        return not (a < 2 or any(a % x == 0 for x in range(2, int(a ** 0.5) + 1)))

    i = 2
    largest_factor = None
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            largest_factor = i
    return max(n, largest_factor) if n > 1 else largest_factor

from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    result = []
    for group in paren_string.split():
        max_nesting = 0
        current_nesting = 0
        for ch in group:
            if ch == '(':
                current_nesting += 1
                if current_nesting > max_nesting:
                    max_nesting = current_nesting
            elif ch == ')':
                current_nesting -= 1
        result.append(max_nesting)
    return result

def correct_bracketing(brackets: str):
    stack = []
    for bracket in brackets:
        if bracket == '(':
            stack.append(bracket)
        elif bracket == ')':
            if not stack:
                return False
            stack.pop()
    return len(stack) == 0

def fibfib(n: int):
    if n == 0:
        return 0
    elif n == 1:
        return 0
    elif n == 2:
        return 1

    a, b, c = 0, 0, 1
    for _ in range(3, n + 1):
        next_fibfib = a + b + c
        a, b, c = b, c, next_fibfib
    return c

def vowels_count(s):
    vowels = 'aeiouAEIOU'
    return sum(1 for char in s if char in vowels)

def circular_shift(x, shift):
    if not (isinstance(x, int) and isinstance(shift, int)):
        raise ValueError("Invalid inputs")
    if x < 0 or shift < 0:
        raise ValueError("Invalid inputs")

    digits = list(str(x))
    n = len(digits)
    shift %= n
    shifted_digits = digits[-shift:] + digits[:-shift]
    return ''.join(shifted_digits)

def pluck(arr):
    if not arr or len(arr) > 10000:
        return []

    smallest_even = float('inf')
    index_of_smallest_even = -1

    for i, value in enumerate(arr):
        if value % 2 == 0 and value < smallest_even:
            smallest_even = value
            index_of_smallest_even = i

    return [smallest_even, index_of_smallest_even] if index_of_smallest_even != -1 else []

def search(lst):
    from collections import Counter

    freq = Counter(lst)
    result = -1

    for num, count in freq.items():
        if count >= num:
            result = max(result, num)

    return result

