def strange_sort_list(lst):
    sorted_lst = sorted(lst)
    result = []
    left, right = 0, len(sorted_lst) - 1

    while left <= right:
        if left == right:
            result.append(sorted_lst[left])
        else:
            result.extend([sorted_lst[left], sorted_lst[right]])
        left += 1
        right -= 1

    return result

import math

def triangle_area(a, b, c):
    assert a > 0 and b > 0 and c > 0, "invalid inputs"

    if a + b <= c or a + c <= b or b + c <= a:
        return -1

    s = (a + b + c) / 2
    area = math.sqrt(s * (s - a) * (s - b) * (s - c))
    return round(area, 2)

def will_it_fly(q, w):
    is_palindrome = lambda lst: lst == lst[::-1]
    return is_palindrome(q) and sum(q) <= w

def total_match(lst1, lst2):
    def char_count(lst):
        return sum(len(s) for s in lst)

    count1 = char_count(lst1)
    count2 = char_count(lst2)

    if count1 < count2:
        return lst1
    elif count2 < count1:
        return lst2
    else:
        return lst1

def is_multiply_prime(a):
    def is_prime(n):
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    primes = []
    for i in range(2, a // 2 + 1):
        if is_prime(i) and a % i == 0:
            primes.append(i)

    while len(primes) > 3:
        primes.pop()

    return len(primes) == 3 and all(is_prime(p) for p in primes)

def is_simple_power(x, n):
    if x < 1 or n <= 1:
        return False
    power = 1
    while power < x:
        power *= n
    return power == x

def iscube(a):
    assert type(a) == int, "invalid inputs"
    return round(a ** (1. / 3)) ** 3 == a

def hex_key(num):
    primes = {2, 3, 5, 7, 11, 13, 17}
    hex_digits = set("0123456789ABCDEF")
    count = 0

    for digit in num:
        if int(digit, 16) in primes and digit in hex_digits:
            count += 1

    return count

from typing import List, Tuple

def sum_product(numbers: List[int]) -> Tuple[int, int]:
    if not numbers:
        return (0, 1)

    total_sum = sum(numbers)
    product = 1
    for num in numbers:
        product *= num

    return (total_sum, product)

def is_happy(s):
    if not isinstance(s, str) or len(s) < 3:
        return False
    for i in range(len(s) - 2):
        if len(set(s[i:i+3])) != 3:
            return False
