def get_row(lst, x):
    coordinates = []
    for row_index, row in enumerate(lst):
        for column_index, value in enumerate(row):
            if value == x:
                coordinates.append((row_index, column_index))

    # Sort by rows first (ascending), then by columns (descending)
    coordinates.sort(key=lambda coord: (coord[0], -coord[1]))
    return coordinates

def sort_array(array):
    if not array:
        return []

    first, *_, last = array
    sum_first_last = first + last

    if sum_first_last % 2 == 0:
        return sorted(array, reverse=True)
    else:
        return sorted(array)

def encrypt(s):
    def shift_char(c, n):
        if c.isalpha():
            offset = ord('a')
            return chr((ord(c) - offset + n) % 26 + offset)
        else:
            return c

    result = ""
    for char in s:
        shifted_char = shift_char(char, 4)
        result += shifted_char
    return result

