def encode(message):
    def shift_vowel(c):
        vowels = 'aeiouAEIOU'
        if c in vowels:
            index = vowels.index(c)
            return vowels[(index + 2) % len(vowels)]
        else:
            return c

    encoded_message = ""
    for char in message:
        if char.isalpha():
            new_char = shift_vowel(char)
            if char.islower():
                new_char = new_char.upper() if new_char.islower() else new_char.lower()
            encoded_message += new_char
        else:
            encoded_message += char
    return encoded_message

