    return y if y % 2 == 0 else y - 1

def rounded_avg(n, m):
    if n > m:
        return -1
    total = (n + m) * (m - n + 1) // 2
    count = m - n + 1
    average = total / count
    rounded = round(average)
    return bin(rounded)

