def is_consonant(ch):
    return ch.isalpha() and not is_vowel(ch)

def get_closest_vowel(word):
    if not word:
        return ""

    n = len(word)
    for i in range(n - 2, 0, -1):
        if is_vowel(word[i]):
            left = word[i - 1]
            right = word[i + 1] if i + 1 < n else ''
            if is_consonant(left) and is_consonant(right):
                return word[i]
    return ""

def match_parens(lst):
    s1, s2 = lst[0], lst[1]

    def is_balanced(s):
        bal = 0
        for ch in s:
            if ch == '(':
                bal += 1
            else:
                bal -= 1
            if bal < 0:
                return False, bal
        return True, bal

    # Try s1 + s2
    bal1, net1 = is_balanced(s1)
    if bal1:
        bal2, net2 = is_balanced(s2)
        if bal2 and net1 + net2 == 0:
            return 'Yes'
    else:
        # If s1 is not balanced, the only way to possibly succeed is if
        # s1's deficit can be compensated by s2's prefix.
        # Actually, we need to check both orders.
        pass

    # Try s2 + s1
    bal2, net2 = is_balanced(s2)
    if bal2:
        bal1, net1 = is_balanced(s1)
        if bal1 and net2 + net1 == 0:
            return 'Yes'

    # More general check: we need to see if any concatenation can be balanced.
    # The problem reduces to checking if there exists an order such that
    # the cumulative balance never goes negative and ends at zero.
    # We can simulate both orders with a stack-like balance check.

    def can_concat(a, b):
        bal = 0
        min_bal = 0
        for ch in a:
            if ch == '(':
                bal += 1
            else:
                bal -= 1
            min_bal = min(min_bal, bal)
        # Now append b
        for ch in b:
            if ch == '(':
                bal += 1
            else:
                bal -= 1
            min_bal = min(min_bal, bal)
        return bal == 0 and min_bal >= 0

    if can_concat(s1, s2) or can_concat(s2, s1):
        return 'Yes'
    return 'No'

