def fix_spaces(text):
    if not isinstance(text, str):
        raise AssertionError("invalid inputs")

    result = []
    i = 0
    n = len(text)

    while i < n:
        if text[i] != ' ':
            result.append(text[i])
            i += 1
        else:
            count = 0
            while i < n and text[i] == ' ':
                count += 1
                i += 1
            if count > 2:
                result.append('-')
            else:
                result.append('_' * count)

    return ''.join(result)

def file_name_check(file_name):
    if not isinstance(file_name, str):
        return "No"

    if file_name.count('.') != 1:
        return "No"

    before_dot, after_dot = file_name.split('.')

    if not before_dot:
        return "No"

    if not before_dot[0].isalpha():
        return "No"

    digit_count = sum(c.isdigit() for c in file_name)
    if digit_count > 3:
        return "No"

    valid_extensions = {'txt', 'exe', 'dll'}
    if after_dot not in valid_extensions:
        return "No"

    return "Yes"

