def int_to_mini_roman(number):
    assert type(number) == int, "invalid inputs"
    assert 1 <= number <= 1000, "invalid inputs"

    val = [
        (1000, 'm'), (900, 'cm'), (500, 'd'), (400, 'cd'),
        (100, 'c'), (90, 'xc'), (50, 'l'), (40, 'xl'),
        (10, 'x'), (9, 'ix'), (5, 'v'), (4, 'iv'),
        (1, 'i')
    ]

    result = []
    for v, symbol in val:
        while number >= v:
            result.append(symbol)
            number -= v
    return ''.join(result)

