    divisible_by_three.sort()
    idx = 0
    for i in range(len(l)):
        if i % 3 == 0:
            result[i] = divisible_by_three[idx]
            idx += 1
    return result

def sort_even(l: list):
    even_vals = sorted([l[i] for i in range(0, len(l), 2)])
    result = l[:]
    for i in range(0, len(l), 2):
        result[i] = even_vals[i // 2]
    return result

