        return s
    result = []
    word_chars = []
    for ch in s:
        if ch == ' ':
            if word_chars:
                word_chars.sort(key=lambda c: ord(c))
                result.append(''.join(word_chars))
                word_chars = []
            result.append(' ')
        else:
            word_chars.append(ch)
