def encode(message):
    vowels = set('aeiouAEIOU')
    result = []
    for ch in message:
        if ch == ' ':
            result.append(' ')
        elif ch.isalpha():
            if ch.lower() in vowels:
                base = ord('a') if ch.islower() else ord('A')
                offset = (ord(ch.lower()) - ord('a') + 2) % 26
                new_ch = chr(base + offset)
                result.append(new_ch.swapcase())
            else:
                result.append(ch.swapcase())
    return ''.join(result)

