def is_sorted(lst):
    if len(lst) < 2:
        return True
    prev = lst[0]
    count = 1
    for num in lst[1:]:
        if num == prev:
            count += 1
            if count > 1:
                return False
        else:
            prev = num
            count = 1
        if num < prev:
            return False
    return True

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def intersection(interval1, interval2):
    start_max = max(interval1[0], interval2[0])
    end_min = min(interval1[1], interval2[1])
    if start_max > end_min:
        return "NO"
    length = end_min - start_max + 1
    return "YES" if is_prime(length) else "NO"

def prod_signs(arr):
    if not arr:
        return None
    sign_product = 1
    magnitude_sum = 0
    for num in arr:
        if num == 0:
            return 0
        elif num < 0:
            sign_product *= -1
        magnitude_sum += abs(num)
    return sign_product * magnitude_sum

def minPath(grid, k):
    N = len(grid)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def dfs(x, y, path):
        if len(path) == k:
            return path
        min_path = None
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N:
                new_path = dfs(nx, ny, path + [grid[nx][ny]])
                if min_path is None or (new_path and (min_path is None or new_path < min_path)):
                    min_path = new_path
        return min_path

    min_path = None
    for i in range(N):
        for j in range(N):
            path = dfs(i, j, [grid[i][j]])
            if min_path is None or (path and (min_path is None or path < min_path)):
                min_path = path
    return min_path

def tri(n):
    if n < 0:
        raise ValueError("n must be a non-negative integer")

    if n == 0:
        return [1]
    elif n == 1:
        return [1, 3]

    tribonacci = [1, 3, 2]
    for i in range(3, n + 1):
        if i % 2 == 0:
            tribonacci.append(1 + i / 2)
        else:
            tribonacci.append(tribonacci[i - 1] + tribonacci[i - 2] + tribonacci[i + 1])
    return tribonacci

def digits(n):
    product = 1
    has_odd = False
    for digit in str(n):
        d = int(digit)
        if d % 2 == 1:
            product *= d
            has_odd = True
    return product if has_odd else 0

def is_nested(s):
    stack = []
    nested = False
    for char in s:
        if char == '[':
            stack.append(char)
        elif char == ']' and stack:
            stack.pop()
            if stack:
                nested = True
    return nested and not stack

def largest_smallest_integers(lst):
    negative_ints = [x for x in lst if x < 0]
    positive_ints = [x for x in lst if x > 0]

    a = max(negative_ints) if negative_ints else None
    b = min(positive_ints) if positive_ints else None

    return (a, b)

def special_factorial(n):
    result = 1
    for i in range(1, n + 1):
        factorial = 1
        for j in range(1, i + 1):
            factorial *= j
        result *= factorial
    return result

def fix_spaces(text):
    """
    Given a string text, replace all spaces in it with underscores, 
    and if a string has more than 2 consecutive spaces, 
    then replace all consecutive spaces with - 

    fix_spaces("Example") == "Example"
    fix_spaces("Example 1") == "Example_1"
    fix_spaces(" Example 2") == "_Example_2"
    fix_spaces(" Example   3") == "_Example-3"
    """
    assert isinstance(text, str), "invalid inputs" # $_CONTRACT_$

    result = []
    space_count = 0

    for char in text:
        if char == ' ':
            space_count += 1
        else:
            if space_count > 2:
                result.append('-')
            elif space_count > 0:
                result.extend(['_'] * space_count)
            result.append(char)
            space_count = 0

    if space_count > 2:
        result.append('-')
    elif space_count > 0:
        result.extend(['_'] * space_count)

    return ''.join(result)

def file_name_check(file_name):
    if not isinstance(file_name, str):
        raise ValueError("Invalid input: file_name must be a string")

    parts = file_name.split('.')
    if len(parts) != 2:
        return 'No'

    prefix, extension = parts

    if not prefix or not prefix[0].isalpha():
        return 'No'

    if not any(extension == ext for ext in ['txt', 'exe', 'dll']):
        return 'No'

    digit_count = sum(c.isdigit() for c in file_name)
    if digit_count > 3:
        return 'No'

    return 'Yes'

def specialFilter(nums):
    def is_odd_and_greater_than_10(num):
        if num <= 10:
            return False
        digits = [int(d) for d in str(abs(num))]
        return all(d % 2 != 0 for d in digits)

    return sum(is_odd_and_greater_than_10(num) for num in nums)

def get_max_triples(n):
    a = [i * i - i + 1 for i in range(1, n + 1)]
    count = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if (a[i] + a[j] + a[k]) % 3 == 0:
                    count += 1
    return count

def bf(planet1, planet2):
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]
    if planet1 not in planets or planet2 not in planets:
        return ()
    index1, index2 = planets.index(planet1), planets.index(planet2)
    if index1 > index2:
        index1, index2 = index2, index1
    return tuple(planets[index1 + 1:index2])

def is_prime(num):
    if num <= 1:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5

    """
    assert type(n) == int, "invalid inputs" # $_CONTRACT_$

    return x if is_prime(n) else y

def Strongest_Extension(class_name, extensions):
    strongest_extension = max(extensions, key=lambda x: (sum(c.isupper() for c in x), -sum(c.islower() for c in x)))
    return f"{class_name}.{strongest_extension}"

def cycpattern_check(a, b):
    if not isinstance(a, str) or not isinstance(b, str):
        raise ValueError("Invalid inputs")

    for i in range(len(b)):
        rotated_b = b[i:] + b[:i]
        if rotated_b in a:
            return True
    return False

def right_angle_triangle(a, b, c):
    sides = sorted([a, b, c])
    return sides[2]**2 == sides[0]**2 + sides[1]**2

def find_max(words):
    max_word = ""
    max_unique_chars = 0
    for word in words:
        unique_chars = set(word)
        if len(unique_chars) > max_unique_chars or (len(unique_chars) == max_unique_chars and word < max_word):
            max_word = word
            max_unique_chars = len(unique_chars)
    return max_word

def eat(number, need, remaining):
    if number < 0 or number > 1000 or need < 0 or need > 1000 or remaining < 0 or remaining > 1000:
        raise ValueError("invalid inputs")

    total_eaten = number + min(need, remaining)
    carrots_left = max(remaining - need, 0)

    return [total_eaten, carrots_left]

def solve(s):
    if any(c.isalpha() for c in s):
        return ''.join(c.swapcase() if c.isalpha() else c for c in s)
    else:
        return s[::-1]

import hashlib

def string_to_md5(text):
    """
    Given a string 'text', return its md5 hash equivalent string.
    If 'text' is an empty string, return None.

    >>> string_to_md5('Hello world') == '3e25960a79dbc69b674cd4ec67a72c62'
    """
    if not text:
        return None
    return hashlib.md5(text.encode()).hexdigest()

def largest_divisor(n: int) -> int:
    for i in range(n - 1, 0, -1):
        if n % i == 0:
            return i

from typing import List


def below_zero(operations: List[int]) -> bool:
    balance = 0
    for operation in operations:
        balance += operation
        if balance < 0:
            return True
    return False

import math

def poly(xs: list, x: float):
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])

def find_zero(xs: list):
    assert isinstance(xs, list) and len(xs) > 0 and len(xs) % 2 == 0, "invalid inputs"
    assert xs[-1] != 0, "invalid inputs"
    assert all(type(x) == int for x in xs), "invalid inputs"

    dxs = [xs[i] * i for i in range(1, len(xs))]

    def func(x):
        return poly(xs, x)

    def derivative(x):
        return poly(dxs, x)

    x, tol = 0, 1e-5
    for _ in range(1000):
        fx = func(x)
        dfx = derivative(x)
        if abs(fx) < tol:
            break
        x = x - fx / dfx

    assert abs(poly(xs, x)) < tol, "invalid inputs"

    return round(x, 2)

def fib4(n: int):
    if n < 2:
        return 0
    elif n == 2:
        return 2
    else:
        a, b, c, d = 0, 0, 2, 0
        for _ in range(3, n + 1):
            a, b, c, d = b, c, d, a + b + c + d
        return d

def decode_shift(s: str) -> str:
    """
    takes as input string encoded with encode_shift function. Returns decoded string.
    """
    return "".join([chr(((ord(ch) - 5 - ord("a")) % 26) + ord("a")) for ch in s])

def correct_bracketing(brackets: str):
    balance = 0
    for bracket in brackets:
        if bracket == '<':
            balance += 1
        elif bracket == '>':
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def largest_prime_factor(n: int):
    """Return the largest prime factor of n. Assume n > 1 and is not a prime.
    >>> largest_prime_factor(13195)
    29
    >>> largest_prime_factor(2048)
    2
    """
    def is_prime(a):
        return not (a < 2 or any(a % x == 0 for x in range(2, int(a ** 0.5) + 1)))

    assert isinstance(n, int), "invalid inputs"
    assert n > 1 and not is_prime(n), "invalid inputs"

    largest_factor = None
    for i in range(2, int(n ** 0.5) + 1):
        while n % i == 0:
            largest_factor = i
            n //= i
    if n > 1:
        largest_factor = n
    return largest_factor

def correct_bracketing(brackets: str):
    balance = 0
    for bracket in brackets:
        if bracket == '(':
            balance += 1
        else:
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def fibfib(n: int) -> int:
    if n == 0 or n == 1:
        return 0
    elif n == 2:
        return 1
    else:
        a, b, c = 0, 0, 1
        for _ in range(3, n + 1):
            a, b, c = b, c, a + b + c
        return c

def pluck(arr):
    if not arr:
        return []

    smallest_even = float('inf')
    index_of_smallest_even = -1

    for i, value in enumerate(arr):
        if value % 2 == 0 and value < smallest_even:
            smallest_even = value
            index_of_smallest_even = i

    if smallest_even == float('inf'):
        return []

    return [smallest_even, index_of_smallest_even]

def search(lst):
    from collections import Counter

    freq = Counter(lst)
    max_val = -1

    for num, count in freq.items():
        if num <= count and num > max_val:
            max_val = num

    return max_val

def is_multiply_prime(a):
    def is_prime(n):
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    primes = [i for i in range(2, 100) if is_prime(i)]

    for i in range(len(primes)):
        for j in range(i, len(primes)):
            for k in range(j, len(primes)):
                if primes[i] * primes[j] * primes[k] == a:
                    return True
    return False

def is_simple_power(x, n):
    assert type(x) == int and type(n) == int, "invalid inputs"
    if x == 1:
        return True
    if n <= 1:
        return False
    power = 1
    while power < x:
        power *= n
    return power == x

def hex_key(num):
    prime_hex_digits = {'2', '3', '5', '7', 'B', 'D'}
    return sum(1 for digit in num if digit in prime_hex_digits)

def decimal_to_binary(decimal):
    if not isinstance(decimal, int) or decimal < 0:
        raise ValueError("Invalid input")

    binary = bin(decimal)[2:]
    return f"db{binary}db"

def is_happy(s):
    if len(s) < 3:
        return False
    for i in range(len(s) - 2):
        if s[i] == s[i+1] or s[i] == s[i+2] or s[i+1] == s[i+2]:
            return False
    return True

def prime_length(string):
    length = len(string)
    if length < 2:
        return False
    for i in range(2, int(length ** 0.5) + 1):
        if length % i == 0:
            return False
    return True

# Test cases
assert prime_length('Hello') == True
assert prime_length('abcdcba') == True
assert prime_length('kittens') == True
assert prime_length('orange') == False

def starts_one_ends(n):
    """
    Given a positive integer n, return the count of the numbers of n-digit
    positive integers that start or end with 1.
    """
    assert type(n) == int and n > 0, "invalid inputs" # $_CONTRACT_$

    if n == 1:
        return 1
    else:
        return 2 * (10 ** (n - 1)) - 10 ** (n - 2)

def get_row(lst, x):
    result = []
    for i, row in enumerate(lst):
        for j, value in enumerate(row[::-1]):
            if value == x:
                result.append((i, len(row) - 1 - j))
    return sorted(result)

def any_int(x, y, z):
    if not all(isinstance(v, int) for v in [x, y, z]):
        raise ValueError("All arguments must be integers")
    return (x + y == z) or (x + z == y) or (y + z == x)

def skjkasdkd(lst):
    def is_prime(a):
        return not (a < 2 or any(a % x == 0 for x in range(2, int(a ** 0.5) + 1)))

    largest_prime = max((x for x in lst if is_prime(x)), default=0)
    return sum(int(digit) for digit in str(largest_prime))

def check_dict_case(d):
    if not d:
        return False

    lower_case = upper_case = None

    for key in d.keys():
        if not isinstance(key, str):
            return False

        if lower_case is None and upper_case is None:
            lower_case = key.islower()
            upper_case = key.isupper()
        elif (lower_case and not key.islower()) or (upper_case and not key.isupper()):
            return False

    return True

def count_up_to(n):
    def is_prime(num):
        if num <= 1:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    result = []
    for i in range(2, n):
        if is_prime(i):
            result.append(i)
    return result

def closest_integer(value):
    try:
        value = float(value)
    except ValueError:
        raise Exception("invalid inputs")

    if value > 0:
        return int(math.floor(value + 0.5))
    else:
        return int(math.ceil(value - 0.5))
